/* AudioWorklet 处理器代码：实时 bitcrush + noise gate */
const WORKLET_CODE = `
class BitCrushProcessor extends AudioWorkletProcessor {
  constructor(){
    super();
    this.bits=8; this.downsample=1; this.noiseThreshold=0; this.dither=0;
    this.hold=[]; this.counter=[];
    this.env=[]; this.noiseFloor=[]; this.gateGain=[]; this.lpState=[];
    this.port.onmessage=(e)=>{
      const d=e.data;
      if(d.bits!==undefined) this.bits=d.bits;
      if(d.downsample!==undefined) this.downsample=d.downsample;
      if(d.noiseThreshold!==undefined) this.noiseThreshold=d.noiseThreshold;
      if(d.dither!==undefined) this.dither=d.dither;
    };
  }
  process(inputs,outputs){
    const input=inputs[0], output=outputs[0];
    if(!input||!input.length) return true;
    const bits=this.bits, down=this.downsample, threshold=this.noiseThreshold, ditherAmt=this.dither;
    const step=bits>1?1/Math.pow(2,bits-1):0;
    for(let c=0;c<output.length;c++){
      const inp=input[c]||[], out=output[c];
      if(this.hold[c]===undefined){
        this.hold[c]=0;this.counter[c]=0;this.env[c]=0;
        this.noiseFloor[c]=0.001;this.gateGain[c]=1;this.lpState[c]=0;
      }
      let hold=this.hold[c], counter=this.counter[c], env=this.env[c];
      let noiseFloor=this.noiseFloor[c], gateGain=this.gateGain[c], lp=this.lpState[c];

      // 块RMS用于自适应底噪估计
      let blockRms=0;
      for(let i=0;i<out.length;i++){ const s=inp[i]||0; blockRms+=s*s; }
      blockRms=Math.sqrt(blockRms/out.length);
      if(blockRms<noiseFloor) noiseFloor=blockRms;
      else noiseFloor=noiseFloor*0.9995+blockRms*0.0005;
      const effThreshold=threshold+noiseFloor*0.8;

      for(let i=0;i<out.length;i++){
        let s=inp[i]||0;
        if(threshold>0.0001){
          const abs=s<0?-s:s;
          if(abs>env) env+=(abs-env)*0.06; else env+=(abs-env)*0.01;
          // 扩展器：低于阈值时强力衰减（四次方），而非简单静音
          let targetGain;
          if(env>effThreshold){ targetGain=1; }
          else{
            const r=env/(effThreshold+0.0001);
            targetGain=Math.max(0.005, r*r*r*r);
          }
          if(targetGain>gateGain) gateGain+=(targetGain-gateGain)*0.25;
          else gateGain+=(targetGain-gateGain)*0.04;
          s*=gateGain;
          // 高频衰减：降噪时同步压制高频嘶声
          const lpCoef=Math.min(0.85, 0.25+threshold*3);
          lp=lp+(s-lp)*lpCoef;
          s=s*0.55+lp*0.45;
        }
        if(counter%down===0){
          if(bits===1) hold=s>=0?0.8:-0.8;
          else{
            // STABLE 1.3 新增：Dither 抖动（TPDF噪声），减少低比特量化失真
            if(ditherAmt>0 && bits<8){
              s += (Math.random()-Math.random()) * step * ditherAmt;
            }
            hold=Math.round(s/step)*step; if(hold>1)hold=1; else if(hold<-1)hold=-1;
          }
        }
        out[i]=hold; counter++;
      }
      this.hold[c]=hold; this.counter[c]=counter; this.env[c]=env;
      this.noiseFloor[c]=noiseFloor; this.gateGain[c]=gateGain; this.lpState[c]=lp;
    }
    return true;
  }
}
registerProcessor('bitcrush',BitCrushProcessor);
`;

