/* ============ AUDIO SETUP ============ */
function ensureCtx(){
  if(!audioCtx){
    audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    lowFilter = audioCtx.createBiquadFilter();
    lowFilter.type = 'lowshelf'; lowFilter.frequency.value = 200; lowFilter.gain.value = 0;
    midFilter = audioCtx.createBiquadFilter();
    midFilter.type = 'peaking'; midFilter.frequency.value = 1000; midFilter.Q.value = 1.0; midFilter.gain.value = 0;
    highFilter = audioCtx.createBiquadFilter();
    highFilter.type = 'highshelf'; highFilter.frequency.value = 4000; highFilter.gain.value = 0;
    // 压缩器
    compressorNode = audioCtx.createDynamicsCompressor();
    compressorNode.threshold.value = -24; compressorNode.knee.value = 30;
    compressorNode.ratio.value = 12; compressorNode.attack.value = 0.003; compressorNode.release.value = 0.25;
    // 混响
    convolverNode = audioCtx.createConvolver();
    convolverNode.buffer = createReverbIR(2.5, 2.5);
    reverbGain = audioCtx.createGain(); reverbGain.gain.value = 0;
    dryGain = audioCtx.createGain(); dryGain.gain.value = 1;
    // 延迟
    delayNode = audioCtx.createDelay(2.0); delayNode.delayTime.value = 0.3;
    delayFeedback = audioCtx.createGain(); delayFeedback.gain.value = 0.35;
    delayWetGain = audioCtx.createGain(); delayWetGain.gain.value = 0;
    delaySendGain = audioCtx.createGain(); delaySendGain.gain.value = 1;
    // 淡入淡出
    fadeGainNode = audioCtx.createGain(); fadeGainNode.gain.value = 1;
    // 频谱仪
    analyserNode = audioCtx.createAnalyser(); analyserNode.fftSize = 256;
    // 主输出
    gainNode = audioCtx.createGain(); gainNode.gain.value = 0.9;
    // STABLE 1.2 新增：声像调节（左右声道平衡）
    pannerNode = audioCtx.createStereoPanner(); pannerNode.pan.value = 0;
    // 连接链
    lowFilter.connect(midFilter); midFilter.connect(highFilter); highFilter.connect(compressorNode);
    compressorNode.connect(dryGain); dryGain.connect(fadeGainNode);
    compressorNode.connect(convolverNode); convolverNode.connect(reverbGain); reverbGain.connect(fadeGainNode);
    compressorNode.connect(delaySendGain); delaySendGain.connect(delayNode);
    delayNode.connect(delayFeedback); delayFeedback.connect(delayNode);
    delayNode.connect(delayWetGain); delayWetGain.connect(fadeGainNode);
    fadeGainNode.connect(analyserNode); analyserNode.connect(gainNode); gainNode.connect(pannerNode); pannerNode.connect(audioCtx.destination);
  }
  return audioCtx;
}
function createReverbIR(duration, decay){
  const rate = audioCtx.sampleRate;
  const len = rate * duration;
  const ir = audioCtx.createBuffer(2, len, rate);
  for(let c=0;c<2;c++){
    const d = ir.getChannelData(c);
    for(let i=0;i<len;i++){ d[i] = (Math.random()*2-1) * Math.pow(1-i/len, decay); }
  }
  return ir;
}

async function initWorklet(){
  if(workletNode) return workletNode;
  const ctx = ensureCtx();
  // 优先用 AudioWorklet（安全检测属性是否存在）
  let useWorklet = false;
  try{ useWorklet = !!(ctx.audioWorklet && ctx.audioWorklet.addModule); }catch(e){ useWorklet = false; }
  if(useWorklet){
    try{
      const blob = new Blob([WORKLET_CODE], {type:'application/javascript'});
      const url = URL.createObjectURL(blob);
      try{
        // 内部超时：addModule 超过1.5秒未完成则降级
        const addPromise = ctx.audioWorklet.addModule(url);
        const timeoutPromise = new Promise((_,rej)=>setTimeout(()=>rej(new Error('addModule timeout')), 1500));
        await Promise.race([addPromise, timeoutPromise]);
        workletNode = new AudioWorkletNode(ctx, 'bitcrush');
        workletNode.connect(lowFilter);
        workletReady = true;
        sendParams();
        return workletNode;
      }finally{
        URL.revokeObjectURL(url);
      }
    }catch(e){
      console.warn('AudioWorklet init failed, fallback:', e);
    }
  }
  // 降级：ScriptProcessorNode
  try{
    workletNode = createScriptProcessorFallback(ctx);
    workletNode.connect(lowFilter);
    workletReady = true;
    sendParams();
    return workletNode;
  }catch(e){
    console.warn('ScriptProcessor also failed, will use bypass mode:', e);
    workletNode = null;
    workletReady = true;
    showToast('当前浏览器不支持实时音效，已切换为直通模式');
    return null;
  }
}

/* ScriptProcessorNode 降级方案（不支持 AudioWorklet 时用） */
function createScriptProcessorFallback(ctx){
  const bufferSize = 4096;
  const processor = ctx.createScriptProcessor(bufferSize, 2, 2);
  let curParams = {bits:8, downsample:1, noisePct:0};
  processor.onaudioprocess = (e)=>{
    const bits = curParams.bits;
    const down = curParams.downsample;
    const threshold = curParams.noisePct / 100 * 0.05;
    const step = bits > 1 ? 1 / Math.pow(2, bits - 1) : 0;
    for(let c = 0; c < e.outputBuffer.numberOfChannels; c++){
      const input = e.inputBuffer.getChannelData(c);
      const output = e.outputBuffer.getChannelData(c);
      let hold = 0, counter = 0;
      for(let i = 0; i < input.length; i++){
        let s = Math.abs(input[i]) < threshold ? 0 : input[i];
        if(counter % down === 0){
          if(bits === 1) hold = s >= 0 ? 0.8 : -0.8;
          else{ hold = Math.round(s / step) * step; hold = Math.max(-1, Math.min(1, hold)); }
        }
        output[i] = hold;
        counter++;
      }
    }
  };
  processor.port = { postMessage: (p)=>{ curParams = p; } };
  return processor;
}

/* 发送实时参数给 worklet（秒响应） */
function sendParams(){
  if(!workletNode) return;
  workletNode.port.postMessage({
    bits: Math.round(parseFloat(bitSlider.value)),
    downsample: parseInt(downSlider.value, 10),
    noiseThreshold: parseInt(noiseSlider.value, 10) / 100 * 0.05,
    dither: ditherOn ? 1 : 0
  });
}

function showToast(msg, isErr){
  toast.textContent = msg;
  toast.className = 'toast show' + (isErr ? ' err' : '');
  clearTimeout(toast._t);
  toast._t = setTimeout(()=>{ toast.className = 'toast'; }, 2200);
}

/* ============ PROGRESS MODAL ============ */
function showProgress(title, pct, showCancel){
  progressTitle.textContent = title;
  progressBar.style.width = (pct || 0) + '%';
  progressPct.textContent = Math.round(pct || 0) + '%';
  progressModal.classList.remove('hidden');
  clearTimeout(cancelShowTimer);
  if(showCancel){
    loadCancelled = false;
    cancelLoadBtn.classList.remove('hidden');
    cancelLoadBtn.classList.add('disabled');
    cancelLoadBtn.disabled = true;
    cancelShowTimer = setTimeout(()=>{
      if(!progressModal.classList.contains('hidden')){
        cancelLoadBtn.classList.remove('disabled');
        cancelLoadBtn.disabled = false;
      }
    }, 2000);
  }else{
    cancelLoadBtn.classList.add('hidden');
    cancelLoadBtn.classList.remove('disabled');
    cancelLoadBtn.disabled = false;
  }
}
function updateProgress(pct){
  progressBar.style.width = pct + '%';
  progressPct.textContent = Math.round(pct) + '%';
}
function hideProgress(){
  progressModal.classList.add('hidden');
  clearInterval(progressTimer);
  progressTimer = null;
  clearTimeout(cancelShowTimer);
  cancelShowTimer = null;
  cancelLoadBtn.classList.add('hidden');
  cancelLoadBtn.classList.remove('disabled');
  cancelLoadBtn.disabled = false;
}
/* 取消加载 */
cancelLoadBtn.addEventListener('click', ()=>{
  if(cancelLoadBtn.disabled) return;
  loadCancelled = true;
  if(loadAbortController) loadAbortController.abort();
  hideProgress();
  showToast('已取消加载');
});
/* 解码没有进度回调，用模拟进度（到85%停住，完成后关闭） */
function startFakeProgress(title, showCancel){
  showProgress(title, 0, showCancel);
  let pct = 0;
  clearInterval(progressTimer);
  progressTimer = setInterval(()=>{
    let step;
    if(pct < 30) step = 0.8 + Math.random() * 1.5;
    else if(pct < 55) step = 0.5 + Math.random() * 1.0;
    else if(pct < 75) step = 0.3 + Math.random() * 0.6;
    else if(pct < 85) step = 0.15 + Math.random() * 0.35;
    else step = 0.05 + Math.random() * 0.1;
    pct += step;
    if(pct > 88) pct = 88;
    updateProgress(pct);
  }, 300);
}

function isSafeUrl(url){
  try{
    const u = new URL(url, window.location.href);
    // 只允许 http/https，禁止内网和本地
    if(u.protocol !== 'http:' && u.protocol !== 'https:') return false;
    const host = u.hostname.toLowerCase();
    // 禁止 localhost 和内网 IP
    if(host === 'localhost' || host.endsWith('.local')) return false;
    if(/^127\./.test(host) || /^192\.168\./.test(host) || /^10\./.test(host)) return false;
    if(/^172\.(1[6-9]|2[0-9]|3[01])\./.test(host)) return false;
    if(/^169\.254\./.test(host)) return false;
    return true;
  }catch(e){ return false; }
}
function sanitizeFilename(name){
  return name.replace(/[\\/:*?"<>|]/g, '_').replace(/\.\.+/g, '.').substring(0, 200) || 'audio';
}
function fmtTime(s){
  const m = Math.floor(s/60), sec = (s%60).toFixed(1);
  return m + ':' + (sec<10?'0':'') + sec;
}

