async function loadFile(file){
  if(!file) return;
  if(!file.type.startsWith('audio/') && !/\.(mp3|wav|ogg|m4a|flac|aac|webm)$/i.test(file.name)){
    showToast('不支持的文件格式', true); return;
  }
  stop();
  loadCancelled = false;
  startFakeProgress('解码中…', true);
  try{
    const ctx = ensureCtx();
    const ab = await file.arrayBuffer();
    if(loadCancelled) return;
    updateProgress(95);
    originalBuffer = await ctx.decodeAudioData(ab.slice(0));
    clearMarkers();
    if(loadCancelled) return;
    currentFileName = file.name.replace(/\.[^.]+$/, '');
    fileNameEl.textContent = file.name;
    fileMetaEl.textContent =
      originalBuffer.numberOfChannels + 'ch · ' +
      originalBuffer.sampleRate + 'Hz · ' +
      fmtTime(originalBuffer.duration) + ' · ' +
      (file.size/1024/1024).toFixed(2) + 'MB';
    clearSelection();
    showWorkspace();
    await processAudio();
    drawWaveform();
    hideProgress();
    showToast('加载完成');
  }catch(err){
    if(loadCancelled){ hideProgress(); return; }
    console.error(err);
    hideProgress();
    showToast('解码失败：' + (err.message||'未知错误'), true);
  }
}

reloadBtn.addEventListener('click', hideWorkspace);

/* ============ URL LOAD（带下载进度 + 取消 + 自动重试） ============ */
async function loadFromUrl(url){
  url = url.trim();
  if(!url) return;
  stop();
  loadCancelled = false;
  loadAbortController = new AbortController();
  const maxRetries = 2;
  for(let attempt = 0; attempt <= maxRetries; attempt++){
    showProgress(attempt > 0 ? '重试下载 (' + attempt + '/' + maxRetries + ')…' : '下载中…', 0, true);
    try{
      const resp = await fetch(url, {mode:'cors', signal: loadAbortController.signal});
      if(!resp.ok) throw new Error('HTTP ' + resp.status);
      const total = parseInt(resp.headers.get('content-length')) || 0;
      let loaded = 0;
      const chunks = [];
      const reader = resp.body.getReader();
      while(true){
        const {done, value} = await reader.read();
        if(done) break;
        chunks.push(value);
        loaded += value.length;
        if(total > 0) updateProgress(loaded / total * 100);
        else updateProgress(Math.min(90, loaded / 1000000 * 10));
      }
      const ab = new Uint8Array(loaded);
      let off = 0;
      for(const c of chunks){ ab.set(c, off); off += c.length; }
      if(loadCancelled) return;
      // 解码
      startFakeProgress('解码中…', true);
      const ctx = ensureCtx();
      originalBuffer = await ctx.decodeAudioData(ab.buffer);
      clearMarkers();
      if(loadCancelled) return;
      const name = url.split('/').pop().split('?')[0] || 'stream';
      currentFileName = name.replace(/\.[^.]+$/, '') || 'audio';
      fileNameEl.textContent = name;
      fileMetaEl.textContent =
        originalBuffer.numberOfChannels + 'ch · ' +
        originalBuffer.sampleRate + 'Hz · ' +
        fmtTime(originalBuffer.duration) + ' · URL';
      clearSelection();
      showWorkspace();
      await processAudio();
      drawWaveform();
      hideProgress();
      showToast('加载完成');
      return;
    }catch(err){
      if(loadCancelled || err.name === 'AbortError'){ hideProgress(); return; }
      if(attempt < maxRetries){
        await new Promise(r => setTimeout(r, 800));
        continue;
      }
      console.error(err);
      hideProgress();
      let msg = err.message || '未知错误';
      if(msg.indexOf('Failed to fetch') >= 0 || msg.indexOf('NetworkError') >= 0){
        msg = '下载失败：可能是 CORS 跨域限制或 URL 不可达';
      }
      showToast('加载失败：' + msg, true);
      return;
    }
  }
}

