/* 代码生成随机示例音乐：6乐器 + 28调式 + 丰富编曲 */
async function generateDemoAudio(){
  const sr = 44100;
  // ===== 12个根音（含升降号）=====
  const roots = [261.63,277.18,293.66,311.13,329.63,349.23,369.99,392.00,415.30,440.00,466.16,493.88];
  const root = roots[Math.floor(Math.random()*roots.length)];
  // ===== 10种调式 =====
  const modes = [
    {name:'major', scale:[0,2,4,5,7,9,11]},
    {name:'natural_minor', scale:[0,2,3,5,7,8,10]},
    {name:'harmonic_minor', scale:[0,2,3,5,7,8,11]},
    {name:'melodic_minor', scale:[0,2,3,5,7,9,11]},
    {name:'dorian', scale:[0,2,3,5,7,9,10]},
    {name:'phrygian', scale:[0,1,3,5,7,8,10]},
    {name:'mixolydian', scale:[0,2,4,5,7,9,10]},
    {name:'lydian', scale:[0,2,4,6,7,9,11]},
    {name:'blues', scale:[0,3,5,6,7,10]},
    {name:'pentatonic_major', scale:[0,2,4,7,9]},
  ];
  const mode = modes[Math.floor(Math.random()*modes.length)];
  // 和弦生成函数（基于调式音阶）
  function getChord(degree, seventh=false){
    const s = mode.scale;
    const rootSemi = s[degree % s.length];
    const octave = Math.floor(degree / s.length);
    const third = s[(degree+2) % s.length] + 12*Math.floor((degree+2)/s.length);
    const fifth = s[(degree+4) % s.length] + 12*Math.floor((degree+4)/s.length);
    if(seventh){
      const seventhN = s[(degree+6) % s.length] + 12*Math.floor((degree+6)/s.length);
      return [rootSemi, third-rootSemi, fifth-rootSemi, seventhN-rootSemi];
    }
    return [rootSemi, third-rootSemi, fifth-rootSemi];
  }
  // ===== 40种和弦进行（4-8小节）=====
  const progressions = [
    [0,4,5,3],[0,5,3,4],[5,3,0,4],[0,3,4,4],[0,5,4,0],[3,4,0,5],
    [0,2,3,4],[4,5,3,0],[0,3,0,4],[0,4,3,4],[5,0,3,4],[0,5,6,4],
    [3,0,4,5],[0,2,4,5],[4,0,5,3],[0,4,1,4],[0,5,1,4],[1,4,0,5],
    [0,3,6,4],[0,6,4,5],[6,4,0,5],[0,4,6,5],[2,5,1,4],[0,2,5,1],
    [0,5,6,3],[3,6,2,5],[0,3,6,2,5,1],[0,4,5,6,5,4],[0,5,3,6,2,5,1,4],
    [0,0,4,4],[5,5,1,1],[4,4,0,0],[0,5,0,5],[1,1,4,4],[5,1,4,5],
  ];
  const prog = progressions[Math.floor(Math.random()*progressions.length)];
  // ===== BPM 60-180 =====
  const bpm = 60 + Math.floor(Math.random()*121);
  const beat = 60 / bpm;
  // ===== 6种编曲风格 =====
  const arrStyles = ['full_rock','piano_ballad','electronic','jazz_trio','guitar_solo','funk'];
  const arrStyle = arrStyles[Math.floor(Math.random()*arrStyles.length)];
  // 每小节拍数
  const beatsPerBar = 4;
  // 段落结构：前奏(2) + 主歌(4) + 副歌(4) + 桥段(2) + 副歌(4) = 16小节
  const sections = [
    {name:'intro', bars:2, intensity:0.3},
    {name:'verse', bars:4, intensity:0.5},
    {name:'chorus', bars:4, intensity:1.0},
    {name:'bridge', bars:2, intensity:0.7},
    {name:'chorus2', bars:4, intensity:1.0},
  ];
  const totalBars = sections.reduce((s,sec)=>s+sec.bars, 0);
  const dur = totalBars * beatsPerBar * beat + 1;
  const ctx = new OfflineAudioContext(2, Math.ceil(sr * dur), sr);
  function note(semi, oct=4){ return root * Math.pow(2, oct-4) * Math.pow(2, semi/12); }
  // ===== 25种鼓点 =====
  const drumPatterns = [
    {kick:[0,2], snare:[1,3], hat:[0,0.5,1,1.5,2,2.5,3,3.5]},
    {kick:[0,1.5,2], snare:[1,3], hat:[0,0.5,1,1.5,2,2.5,3,3.5]},
    {kick:[0,2], snare:[1,3], hat:[0,0.25,0.5,0.75,1,1.25,1.5,1.75,2,2.25,2.5,2.75,3,3.25,3.5,3.75]},
    {kick:[0,0.5,2,2.5], snare:[1,3], hat:[0,0.5,1,1.5,2,2.5,3,3.5]},
    {kick:[0,2,3], snare:[1,3], hat:[0,0.5,1,1.5,2,2.5,3,3.5]},
    {kick:[0,0.5,2], snare:[1,3], hat:[0,0.25,0.5,0.75,1,1.25,1.5,1.75,2,2.25,2.5,2.75,3,3.25,3.5,3.75]},
    {kick:[0,2], snare:[1,3], hat:[0,1,2,3], ride:[0,0.5,1,1.5,2,2.5,3,3.5]},
    {kick:[0,1.75,2,3.75], snare:[1,3], hat:[0,0.5,1,1.5,2,2.5,3,3.5]},
    {kick:[0,2], snare:[1,3], hat:[0,0.5,1,1.5,2,2.5,3,3.5], tom:[1.5]},
    {kick:[0,0.25,0.5,2,2.25,2.5], snare:[1,3], hat:[0,0.5,1,1.5,2,2.5,3,3.5]},
    {kick:[0,2], snare:[1,3], hat:[]}, // 极简
    {kick:[0,1,2,3], snare:[], hat:[0,0.5,1,1.5,2,2.5,3,3.5]}, // 四 on floor
    {kick:[0,2], snare:[0.5,1.5,2.5,3.5], hat:[0,0.5,1,1.5,2,2.5,3,3.5]}, // 反拍
    {kick:[0,0.75,2,2.75], snare:[1,3], hat:[0,0.5,1,1.5,2,2.5,3,3.5]},
    {kick:[0,2], snare:[1,3], hat:[0,1,2,3], tom:[0.5,1.5,2.5,3.5]},
    {kick:[0,1.5,2], snare:[0.5,2.5], hat:[0,0.5,1,1.5,2,2.5,3,3.5]},
    {kick:[0,2,3.5], snare:[1,3], hat:[0,0.5,1,1.5,2,2.5,3,3.5]},
    {kick:[0,0.5,1.5,2,2.5,3.5], snare:[1,3], hat:[0,0.25,0.5,0.75,1,1.25,1.5,1.75,2,2.25,2.5,2.75,3,3.25,3.5,3.75]},
    {kick:[0,2], snare:[1,3], hat:[0.25,0.75,1.25,1.75,2.25,2.75,3.25,3.75]}, //  offbeat hat
    {kick:[0,1,2,3], snare:[0.5,1.5,2.5,3.5], hat:[0,0.5,1,1.5,2,2.5,3,3.5]},
    {kick:[0,2], snare:[1,3], hat:[0,0.5,1,1.5,2,2.5,3,3.5], crash:[0]},
    {kick:[0,2], snare:[1,3], hat:[0,0.5,1,1.5,2,2.5,3,3.5], crash:[0,2]},
    {kick:[0.5,2.5], snare:[0,2], hat:[0,0.5,1,1.5,2,2.5,3,3.5]}, // 雷鬼
    {kick:[0,2], snare:[1,3], hat:[0,1,2,3], ride:[0.5,1.5,2.5,3.5]},
    {kick:[0,1,2,3], snare:[1,3], hat:[0,0.5,1,1.5,2,2.5,3,3.5]},
  ];
  const drumPat = drumPatterns[Math.floor(Math.random()*drumPatterns.length)];
  // ===== 失真曲线（随机强度）=====
  const distAmt = 3 + Math.random()*5;
  const dist = new Float32Array(512);
  for(let i=0;i<512;i++){ const x=(i/256)-1; dist[i]=Math.tanh(x*distAmt); }
  const softDistAmt = 1.5 + Math.random()*2;
  const softDist = new Float32Array(512);
  for(let i=0;i<512;i++){ const x=(i/256)-1; softDist[i]=Math.tanh(x*softDistAmt); }
  // ===== 乐器函数 =====
  function kick(t, vol=0.45){
    const o=ctx.createOscillator(); o.type='sine';
    o.frequency.setValueAtTime(160,t); o.frequency.exponentialRampToValueAtTime(35,t+0.12);
    const g=ctx.createGain(); g.gain.setValueAtTime(vol,t);
    g.gain.exponentialRampToValueAtTime(0.001,t+0.18);
    o.connect(g); g.connect(ctx.destination); o.start(t); o.stop(t+0.2);
  }
  function snare(t, vol=0.35){
    const n=ctx.createBufferSource(); const b=ctx.createBuffer(1,sr*0.25,sr); const d=b.getChannelData(0);
    for(let i=0;i<d.length;i++) d[i]=Math.random()*2-1; n.buffer=b;
    const f=ctx.createBiquadFilter(); f.type='bandpass'; f.frequency.value=1800; f.Q.value=0.8;
    const g=ctx.createGain(); g.gain.setValueAtTime(vol,t);
    g.gain.exponentialRampToValueAtTime(0.001,t+0.18);
    n.connect(f); f.connect(g); g.connect(ctx.destination); n.start(t); n.stop(t+0.25);
    const o=ctx.createOscillator(); o.type='triangle'; o.frequency.value=180;
    const og=ctx.createGain(); og.gain.setValueAtTime(vol*0.5,t);
    og.gain.exponentialRampToValueAtTime(0.001,t+0.1);
    o.connect(og); og.connect(ctx.destination); o.start(t); o.stop(t+0.12);
  }
  function hihat(t, vol=0.09){
    const n=ctx.createBufferSource(); const b=ctx.createBuffer(1,sr*0.06,sr); const d=b.getChannelData(0);
    for(let i=0;i<d.length;i++) d[i]=Math.random()*2-1; n.buffer=b;
    const f=ctx.createBiquadFilter(); f.type='highpass'; f.frequency.value=8000;
    const g=ctx.createGain(); g.gain.setValueAtTime(vol,t);
    g.gain.exponentialRampToValueAtTime(0.001,t+0.05);
    n.connect(f); f.connect(g); g.connect(ctx.destination); n.start(t); n.stop(t+0.06);
  }
  function ride(t, vol=0.08){
    const n=ctx.createBufferSource(); const b=ctx.createBuffer(1,sr*0.3,sr); const d=b.getChannelData(0);
    for(let i=0;i<d.length;i++) d[i]=Math.random()*2-1; n.buffer=b;
    const f=ctx.createBiquadFilter(); f.type='bandpass'; f.frequency.value=5000; f.Q.value=2;
    const g=ctx.createGain(); g.gain.setValueAtTime(vol,t);
    g.gain.exponentialRampToValueAtTime(0.001,t+0.25);
    n.connect(f); f.connect(g); g.connect(ctx.destination); n.start(t); n.stop(t+0.3);
  }
  function tom(t, vol=0.25){
    const o=ctx.createOscillator(); o.type='sine';
    o.frequency.setValueAtTime(200,t); o.frequency.exponentialRampToValueAtTime(80,t+0.2);
    const g=ctx.createGain(); g.gain.setValueAtTime(vol,t);
    g.gain.exponentialRampToValueAtTime(0.001,t+0.25);
    o.connect(g); g.connect(ctx.destination); o.start(t); o.stop(t+0.3);
  }
  function crash(t, vol=0.2){
    const n=ctx.createBufferSource(); const b=ctx.createBuffer(1,sr*1.0,sr); const d=b.getChannelData(0);
    for(let i=0;i<d.length;i++) d[i]=(Math.random()*2-1)*(1-i/d.length); n.buffer=b;
    const f=ctx.createBiquadFilter(); f.type='highpass'; f.frequency.value=4000;
    const g=ctx.createGain(); g.gain.setValueAtTime(vol,t);
    g.gain.exponentialRampToValueAtTime(0.001,t+0.8);
    n.connect(f); f.connect(g); g.connect(ctx.destination); n.start(t); n.stop(t+1.0);
  }
  function bass(freq, t, d, vol=0.18){
    const o=ctx.createOscillator(); o.type=Math.random()<0.5?'triangle':'sawtooth'; o.frequency.value=freq;
    const f=ctx.createBiquadFilter(); f.type='lowpass'; f.frequency.value=600+Math.random()*400;
    const g=ctx.createGain();
    g.gain.setValueAtTime(0,t);
    g.gain.linearRampToValueAtTime(vol,t+0.01);
    g.gain.setValueAtTime(vol*0.8,t+d*0.5);
    g.gain.exponentialRampToValueAtTime(0.001,t+d);
    o.connect(f); f.connect(g); g.connect(ctx.destination); o.start(t); o.stop(t+d+0.05);
  }
  function piano(freq, t, d, vol=0.16){
    [[1,1],[2,0.5],[3,0.25],[4,0.12]].forEach(([mult,v])=>{
      const o=ctx.createOscillator(); o.type='sine'; o.frequency.value=freq*mult;
      const g=ctx.createGain();
      g.gain.setValueAtTime(0,t);
      g.gain.linearRampToValueAtTime(vol*v,t+0.003);
      g.gain.exponentialRampToValueAtTime(0.001,t+d);
      o.connect(g); g.connect(ctx.destination); o.start(t); o.stop(t+d+0.05);
    });
  }
  function guitar(freq, t, d, vol=0.13){
    const o=ctx.createOscillator(); o.type=Math.random()<0.5?'square':'sawtooth'; o.frequency.value=freq;
    const s=ctx.createWaveShaper(); s.curve=softDist;
    const f=ctx.createBiquadFilter(); f.type='lowpass'; f.frequency.value=2000+Math.random()*1500;
    const g=ctx.createGain();
    g.gain.setValueAtTime(0,t);
    g.gain.linearRampToValueAtTime(vol,t+0.006);
    g.gain.setValueAtTime(vol*0.7,t+d*0.3);
    g.gain.exponentialRampToValueAtTime(0.001,t+d);
    o.connect(s); s.connect(f); f.connect(g); g.connect(ctx.destination);
    o.start(t); o.stop(t+d+0.05);
  }
  function elecGuitar(freq, t, d, vol=0.16){
    const o=ctx.createOscillator(); o.type='sawtooth'; o.frequency.value=freq;
    const lfo=ctx.createOscillator(); lfo.type='sine'; lfo.frequency.value=4+Math.random()*4;
    const lfoGain=ctx.createGain(); lfoGain.gain.value=freq*(0.01+Math.random()*0.03);
    lfo.connect(lfoGain); lfoGain.connect(o.frequency);
    const s=ctx.createWaveShaper(); s.curve=dist;
    const f=ctx.createBiquadFilter(); f.type='lowpass'; f.frequency.value=1200+Math.random()*1000;
    const g=ctx.createGain();
    g.gain.setValueAtTime(0,t);
    g.gain.linearRampToValueAtTime(vol,t+0.03);
    g.gain.setValueAtTime(vol,t+d*0.65);
    g.gain.exponentialRampToValueAtTime(0.001,t+d);
    o.connect(s); s.connect(f); f.connect(g); g.connect(ctx.destination);
    o.start(t); o.stop(t+d+0.1);
    lfo.start(t); lfo.stop(t+d+0.1);
  }
  function synthPad(freq, t, d, vol=0.07){
    [1, 1.005, 0.995].forEach(det=>{
      const o=ctx.createOscillator(); o.type=Math.random()<0.5?'sawtooth':'square'; o.frequency.value=freq*det;
      const f=ctx.createBiquadFilter(); f.type='lowpass'; f.frequency.value=800+Math.random()*800;
      const g=ctx.createGain();
      g.gain.setValueAtTime(0,t);
      g.gain.linearRampToValueAtTime(vol,t+d*0.2);
      g.gain.setValueAtTime(vol,t+d*0.8);
      g.gain.linearRampToValueAtTime(0,t+d);
      o.connect(f); f.connect(g); g.connect(ctx.destination);
      o.start(t); o.stop(t+d+0.05);
    });
  }
  function pluck(freq, t, d, vol=0.12){
    const o=ctx.createOscillator(); o.type='triangle'; o.frequency.value=freq;
    const g=ctx.createGain();
    g.gain.setValueAtTime(vol,t);
    g.gain.exponentialRampToValueAtTime(0.001,t+d);
    o.connect(g); g.connect(ctx.destination); o.start(t); o.stop(t+d+0.05);
  }
  // ===== 改进的旋律生成 =====
  function genMelody(totalBeats){
    const mel = [];
    const scaleLen = mode.scale.length;
    let cur = Math.floor(Math.random()*scaleLen);
    let remaining = totalBeats;
    // 旋律轮廓：随机选择
    const contours = ['up','down','wave','repeat','random'];
    const contour = contours[Math.floor(Math.random()*contours.length)];
    let contourDir = 1;
    while(remaining > 0){
      // 节奏型：八分、四分、附点、二分、十六分、休止
      const r = Math.random();
      let len;
      if(r < 0.15) len = 0.5;        // 八分
      else if(r < 0.25) len = 0.25;  // 十六分
      else if(r < 0.35) len = 1.5;   // 附点四分
      else if(r < 0.45) len = 2;     // 二分
      else if(r < 0.55) len = 0;     // 休止
      else len = 1;                  // 四分
      const actualLen = Math.min(len, remaining);
      if(actualLen <= 0){ remaining -= 0.25; continue; }
      // 旋律轮廓控制
      let step;
      if(contour === 'up') step = Math.floor(Math.random()*3);
      else if(contour === 'down') step = -Math.floor(Math.random()*3);
      else if(contour === 'wave'){ step = contourDir * (Math.floor(Math.random()*3)-1); if(Math.random()<0.2) contourDir *= -1; }
      else if(contour === 'repeat') step = Math.random()<0.7 ? 0 : Math.floor(Math.random()*3)-1;
      else step = Math.floor(Math.random()*7)-3; // 大跳
      // 偶尔大跳
      if(Math.random() < 0.1) step = Math.floor(Math.random()*9)-4;
      cur += step;
      cur = Math.max(0, Math.min(scaleLen*3-1, cur));
      const octave = 4 + Math.floor(cur / scaleLen);
      const degree = cur % scaleLen;
      if(len === 0){
        mel.push([0, actualLen]); // 休止
      }else{
        mel.push([note(mode.scale[degree], octave), actualLen]);
      }
      remaining -= actualLen;
    }
    return mel;
  }
  // ===== 编曲：按段落和风格 =====
  function playSection(section, startT){
    let t = startT;
    const intensity = section.intensity;
    const useDrums = arrStyle !== 'piano_ballad' || intensity > 0.4;
    const useBass = intensity > 0.2;
    const usePiano = arrStyle === 'piano_ballad' || arrStyle === 'full_rock' || arrStyle === 'jazz_trio' || intensity > 0.5;
    const useGuitar = arrStyle === 'full_rock' || arrStyle === 'guitar_solo' || arrStyle === 'funk' || (intensity > 0.6 && Math.random()<0.5);
    const useElecGuitar = arrStyle === 'full_rock' || arrStyle === 'guitar_solo' || (intensity > 0.7 && Math.random()<0.5);
    const useSynth = arrStyle === 'electronic' || (intensity > 0.5 && Math.random()<0.3);
    const usePluck = arrStyle === 'funk' || arrStyle === 'electronic';
    for(let bar=0; bar<section.bars; bar++){
      const ci = (bar + Math.floor(startT/(beatsPerBar*beat))) % prog.length;
      const chord = getChord(prog[ci], Math.random()<0.3);
      const chordNotes = chord.map(s => note(s, 4));
      const rootNote = note(chord[0], 3);
      const barVol = intensity;
      // 鼓
      if(useDrums){
        for(let b=0;b<beatsPerBar;b++){
          const bt=t+b*beat;
          (drumPat.kick||[]).forEach(k=>{ if(k===b) kick(bt, 0.4*barVol); });
          (drumPat.snare||[]).forEach(s=>{ if(s===b) snare(bt, 0.3*barVol); });
          (drumPat.hat||[]).forEach(h=>hihat(bt+h*beat, 0.07*barVol));
          (drumPat.ride||[]).forEach(r=>ride(bt+r*beat, 0.06*barVol));
          (drumPat.tom||[]).forEach(tm=>{ if(tm===b) tom(bt, 0.2*barVol); });
          (drumPat.crash||[]).forEach(c=>{ if(c===b && bar===0) crash(bt, 0.15*barVol); });
        }
      }
      // 贝斯
      if(useBass){
        const bassPattern = Math.floor(Math.random()*3);
        if(bassPattern===0){ // 每拍根音
          for(let b=0;b<beatsPerBar;b++) bass(rootNote, t+b*beat, beat*0.9, 0.15*barVol);
        }else if(bassPattern===1){ // 根五根五
          bass(rootNote, t, beat*0.9, 0.16*barVol);
          bass(note(chord[0]+7, 3), t+beat, beat*0.9, 0.14*barVol);
          bass(rootNote, t+beat*2, beat*0.9, 0.16*barVol);
          bass(note(chord[0]+7, 3), t+beat*3, beat*0.9, 0.14*barVol);
        }else{ //  walking bass
          for(let b=0;b<beatsPerBar;b++){
            const semi = chord[0] + (b%2===0 ? 0 : (b===1?4:7));
            bass(note(semi, 3), t+b*beat, beat*0.85, 0.14*barVol);
          }
        }
      }
      // 钢琴/和弦垫
      if(usePiano){
        if(Math.random()<0.5){ // 柱式和弦
          for(let b=0;b<beatsPerBar;b+=2){
            chordNotes.forEach(n=>piano(n, t+b*beat, beat*1.8, (b===0?0.15:0.1)*barVol));
          }
        }else{ // 分解和弦
          const pat = [chordNotes[0],chordNotes[1],chordNotes[2],chordNotes[1],chordNotes[0],chordNotes[2],chordNotes[1],chordNotes[2]];
          for(let i=0;i<8;i++) piano(pat[i], t+i*beat*0.5, beat*0.4, 0.1*barVol);
        }
      }
      // 合成器垫音
      if(useSynth){
        synthPad(chordNotes[0], t, beat*beatsPerBar, 0.05*barVol);
        if(chordNotes.length>2) synthPad(chordNotes[2], t, beat*beatsPerBar, 0.04*barVol);
      }
      // 吉他
      if(useGuitar){
        if(arrStyle==='funk'){ // 放克切音
          for(let b=0;b<beatsPerBar;b++){
            if(Math.random()<0.7) guitar(chordNotes[b%chordNotes.length], t+b*beat+beat*0.1, beat*0.3, 0.1*barVol);
          }
        }else{ // 普通分解
          const pat=[chordNotes[0],chordNotes[1],chordNotes[2],chordNotes[1]];
          for(let i=0;i<4;i++) guitar(pat[i], t+i*beat, beat*0.45, 0.1*barVol);
        }
      }
      // 拨弦
      if(usePluck){
        for(let b=0;b<beatsPerBar;b++){
          if(Math.random()<0.6) pluck(chordNotes[Math.floor(Math.random()*chordNotes.length)], t+b*beat+beat*0.25, beat*0.3, 0.09*barVol);
        }
      }
      t += beat*beatsPerBar;
    }
    return t;
  }
  // 播放所有段落
  let curT = 0;
  for(const sec of sections){
    curT = playSection(sec, curT);
  }
  // ===== 主旋律（电吉他/钢琴，按段落变化）=====
  const melody = genMelody(totalBars * beatsPerBar);
  let mt = 0;
  let melodyBar = 0;
  for(let loop=0; loop<1; loop++){
    for(let i=0;i<melody.length;i++){
      if(melody[i][0] > 0){
        // 主歌用钢琴，副歌用电吉他
        const curSec = sections.find(s => {
          const start = sections.slice(0, sections.indexOf(s)).reduce((a,b)=>a+b.bars,0);
          return melodyBar >= start && melodyBar < start + s.bars;
        });
        if(curSec && curSec.intensity > 0.6){
          elecGuitar(melody[i][0], mt, beat*melody[i][1]*0.92, 0.13);
        }else{
          piano(melody[i][0], mt, beat*melody[i][1]*0.9, 0.12);
        }
      }
      mt += beat*melody[i][1];
      melodyBar = Math.floor(mt / (beatsPerBar*beat));
    }
  }
  return await ctx.startRendering();
}

