/* ============ PROCESSING PIPELINE: NOISE GATE -> BITCRUSH (EQ is real-time) ============ */

/* 导出时用：把 buffer 通过当前 EQ 设置离线渲染 */
async function renderWithEQ(buffer){
  const low = parseFloat(eqLowSlider.value);
  const mid = parseFloat(eqMidSlider.value);
  const high = parseFloat(eqHighSlider.value);
  if(low === 0 && mid === 0 && high === 0) return buffer;
  const ctx = new OfflineAudioContext(buffer.numberOfChannels, buffer.length, buffer.sampleRate);
  const src = ctx.createBufferSource();
  src.buffer = buffer;
  const lf = ctx.createBiquadFilter();
  lf.type = 'lowshelf'; lf.frequency.value = 200; lf.gain.value = low;
  const mf = ctx.createBiquadFilter();
  mf.type = 'peaking'; mf.frequency.value = 1000; mf.Q.value = 1.0; mf.gain.value = mid;
  const hf = ctx.createBiquadFilter();
  hf.type = 'highshelf'; hf.frequency.value = 4000; hf.gain.value = high;
  src.connect(lf); lf.connect(mf); mf.connect(hf); hf.connect(ctx.destination);
  src.start();
  return await ctx.startRendering();
}

/* 加强降噪：自适应底噪 + 扩展器（四次方衰减）+ 高频嘶声压制 */
function applyNoiseGate(input, output, len, threshold){
  if(threshold <= 0.0001){
    output.set(input);
    return;
  }
  let env = 0, noiseFloor = 0.001, gateGain = 1, lp = 0;
  const blockSize = 256;
  for(let i = 0; i < len; i++){
    // 每blockSize更新一次底噪估计
    if(i % blockSize === 0){
      let rms = 0;
      const end = Math.min(i + blockSize, len);
      for(let j = i; j < end; j++) rms += input[j]*input[j];
      rms = Math.sqrt(rms / (end - i));
      if(rms < noiseFloor) noiseFloor = rms;
      else noiseFloor = noiseFloor * 0.999 + rms * 0.001;
    }
    const s = input[i];
    const abs = s < 0 ? -s : s;
    if(abs > env) env += (abs - env) * 0.06;
    else env += (abs - env) * 0.01;
    const effThreshold = threshold + noiseFloor * 0.8;
    let targetGain;
    if(env > effThreshold){
      targetGain = 1;
    }else{
      const r = env / (effThreshold + 0.0001);
      targetGain = Math.max(0.005, r * r * r * r);
    }
    if(targetGain > gateGain) gateGain += (targetGain - gateGain) * 0.25;
    else gateGain += (targetGain - gateGain) * 0.04;
    let out = s * gateGain;
    // 高频衰减
    const lpCoef = Math.min(0.85, 0.25 + threshold * 3);
    lp += (out - lp) * lpCoef;
    out = out * 0.55 + lp * 0.45;
    output[i] = out;
  }
}

/* 主处理：降噪 + bitcrush（EQ 实时，不在此处理） */
async function processAudio(){
  if(!originalBuffer || isProcessing) return;
  isProcessing = true;
  try{
    const bits = Math.round(parseFloat(bitSlider.value));
    const down = parseInt(downSlider.value, 10);
    const noisePct = parseInt(noiseSlider.value, 10);
    const threshold = noisePct / 100 * 0.05;

    const ctx = ensureCtx();
    const ch = originalBuffer.numberOfChannels;
    const len = originalBuffer.length;
    const sr = originalBuffer.sampleRate;

    // 降噪
    const gatedBuffer = ctx.createBuffer(ch, len, sr);
    for(let c = 0; c < ch; c++){
      applyNoiseGate(originalBuffer.getChannelData(c), gatedBuffer.getChannelData(c), len, threshold);
    }

    // bitcrush（量化 + 降采样保持）
    processedBuffer = ctx.createBuffer(ch, len, sr);
    const step = bits > 1 ? 1 / Math.pow(2, bits - 1) : 0;
    for(let c = 0; c < ch; c++){
      const input = gatedBuffer.getChannelData(c);
      const output = processedBuffer.getChannelData(c);
      let hold = 0;
      let counter = 0;
      for(let i = 0; i < len; i++){
        if(counter % down === 0){
          const s = input[i];
          if(bits === 1){
            hold = s >= 0 ? 0.8 : -0.8;
          }else{
            hold = Math.round(s / step) * step;
            if(hold > 1) hold = 1;
            else if(hold < -1) hold = -1;
          }
        }
        output[i] = hold;
        counter++;
      }
    }
    exportHint.textContent =
      bits + 'bit / ' + down + 'x / 降噪' + noisePct + '% / EQ(' +
      eqLowSlider.value + ',' + eqMidSlider.value + ',' + eqHighSlider.value + ')dB';
  }finally{
    isProcessing = false;
  }
}

/* 离线更新 processedBuffer（用于波形显示和导出），播放声音由 worklet 实时处理不中断 */
let pendingProcess = false;
function scheduleProcess(){
  pendingProcess = true;
  clearTimeout(processTimer);
  processTimer = setTimeout(async ()=>{
    if(isProcessing){ return; } // 正在处理，等完成后由 pending 触发
    pendingProcess = false;
    await processAudio();
    drawWaveform();
    // 处理期间有新参数变化，再跑一次
    if(pendingProcess){
      pendingProcess = false;
      await processAudio();
      drawWaveform();
    }
  }, 30);
}

