/* 离线导出原曲 */
async function doExportOriginal(){
  const suffix = bypassToggle.checked ? '_bypass' : '_' + Math.round(parseFloat(bitSlider.value)) + 'bit_' + downSlider.value + 'x';
  try{
    showProgress('导出中…', 0);
    const srcBuf = bypassToggle.checked ? originalBuffer : processedBuffer;
    if(!srcBuf) throw new Error('无处理后音频');
    updateProgress(20);
    let finalBuf = await renderWithEQ(srcBuf);
    updateProgress(50);
    // 音量归一化
    if(normalizeToggle.checked){
      updateProgress(60);
      finalBuf = normalizeBuffer(finalBuf);
    }
    updateProgress(70);
    const result = await encodeAudio(finalBuf, exportFormat);
    updateProgress(100);
    hideProgress();
    const url = URL.createObjectURL(result.blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = sanitizeFilename(currentFileName) + suffix + '.' + result.ext;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(()=> URL.revokeObjectURL(url), 1000);
    showToast('已导出 ' + (result.blob.size/1024/1024).toFixed(2) + 'MB (' + result.ext.toUpperCase() + ')');
  }catch(e){
    console.error(e);
    hideProgress();
    showToast('导出失败: ' + (e.message || '未知错误'), true);
  }
}

