/* --- 音量归一化 --- */
function normalizeBuffer(buffer){
  const ch = buffer.numberOfChannels;
  let peak = 0;
  for(let c=0;c<ch;c++){
    const d = buffer.getChannelData(c);
    for(let i=0;i<d.length;i++){ if(Math.abs(d[i]) > peak) peak = Math.abs(d[i]); }
  }
  if(peak < 0.01 || peak >= 0.99) return buffer;
  const gain = 0.99 / peak;
  const ctx = ensureCtx();
  const nb = ctx.createBuffer(ch, buffer.length, buffer.sampleRate);
  for(let c=0;c<ch;c++){
    const src = buffer.getChannelData(c);
    const dst = nb.getChannelData(c);
    for(let i=0;i<src.length;i++) dst[i] = Math.max(-1, Math.min(1, src[i]*gain));
  }
  return nb;
}